import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(this);
        // fund owner
        vm.deal(owner, 1 ether);
        // send 100 wei to contract via sendMoney
        c.sendMoney{value: 100}(address(0xdead), 100 wei);
        // now contract balance = 100 wei
        // record owner balance before withdrawAll
        uint256 ownerBalanceBefore = owner.balance;
        // call withdrawAll
        c.withdrawAll();
        // owner balance difference
        uint256 diff = owner.balance - ownerBalanceBefore;
        // In reference, withdrawAll sends contract.balance (100 wei) => diff == 100
        // In buggy, withdrawAll sends 0 => diff == 0
        assertTrue(diff == 100 wei, "Owner should receive 100 wei from withdrawAll");
    }
}

